function _recordRandomnessRequest(
        uint256 _requestId,
        uint256 _collectionId,
        uint256 _tokenId,
        uint256 _randomizerEpoch
    ) internal {
        if (_requestId == 0) {
            revert UnknownRandomnessRequest(_requestId);
        }
        if (randomnessRequests[_requestId].state != RandomnessRequestState.None) {
